{"file_path":"src/parse.js","content":"/** URI template parsing into literal and expression parts. */

/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

const OPERATOR_CHARS = '+#./;?&';
const RESERVED_OPERATOR_CHARS = '=,!@|';

const NAME_GROUP = '(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})';
const NAME_RE = new RegExp(`^${NAME_GROUP}+(?:\\.${NAME_GROUP}+)*$`);
const MAX_LENGTH_RE = /^[1-9][0-9]{0,3}$/;

function validateName(name, braceIndex) {
  if (!NAME_RE.test(name)) {
    throw new UriTemplateError(`invalid variable name '${name}' at ${braceIndex}`, braceIndex);
  }
}

function parseVarSpec(spec, braceIndex) {
  if (spec === '') {
    throw new UriTemplateError(`empty variable specification at ${braceIndex}`, braceIndex);
  }
  let explode = false;
  let maxLength = null;
  let name;
  if (spec.endsWith('*')) {
    explode = true;
    name = spec.slice(0, -1);
    validateName(name, braceIndex);
  } else if (spec.includes(':')) {
    const idx = spec.indexOf(':');
    name = spec.slice(0, idx);
    const mod = spec.slice(idx + 1);
    validateName(name, braceIndex);
    if (!MAX_LENGTH_RE.test(mod)) {
      throw new UriTemplateError(`invalid prefix modifier ':${mod}' at ${braceIndex}`, braceIndex);
    }
    maxLength = Number.parseInt(mod, 10);
  } else {
    name = spec;
    validateName(name, braceIndex);
  }
  return { name, explode, maxLength };
}

function parseExpression(content, braceIndex) {
  if (content === '') {
    throw new UriTemplateError(`empty expression at ${braceIndex}`, braceIndex);
  }
  let operator = '';
  let rest = content;
  const first = content[0];
  if (OPERATOR_CHARS.includes(first)) {
    operator = first;
    rest = content.slice(1);
  } else if (RESERVED_OPERATOR_CHARS.includes(first)) {
    throw new UriTemplateError(`reserved operator '${first}' at ${braceIndex}`, braceIndex);
  }
  const specs = rest.split(',');
  const variables = specs.map((spec) => parseVarSpec(spec, braceIndex));
  return { type: 'expression', operator, variables };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');
  const parts = [];
  let literal = '';
  let i = 0;
  while (i < template.length) {
    const ch = template[i];
    if (ch === '{') {
      if (literal) {
        parts.push({ type: 'literal', value: literal });
        literal = '';
      }
      const start = i;
      const end = template.indexOf('}', i + 1);
      if (end === -1) {
        throw new UriTemplateError(`unterminated expression at ${start}`, start);
      }
      const content = template.slice(i + 1, end);
      parts.push(parseExpression(content, start));
      i = end + 1;
    } else if (ch === '}') {
      throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    } else {
      literal += ch;
      i += 1;
    }
  }
  if (literal) parts.push({ type: 'literal', value: literal });
  return parts;
}
"}

