function encode(str, keepReserved) {
  let result = '';
  let i = 0;
  while (i < str.length) {
    if (keepReserved && str[i] === '%' && PCT_TRIPLET_RE.test(str.slice(i + 1, i + 3))) {
      result += str.slice(i, i + 3);
      i += 3;
      continue;
    }
    const ch = str[i];
    if (UNRESERVED_RE.test(ch) || (keepReserved && RESERVED_RE.test(ch))) {
      result += ch;
      i += 1;
      continue;
    }
    const codePoint = str.codePointAt(i);
    const chStr = String.fromCodePoint(codePoint);
    const bytes = Buffer.from(chStr, 'utf8');
    for (const byte of bytes) {
      result += `%${byte.toString(16).toUpperCase().padStart(2, '0')}`;
    }
    i += chStr.length;
  }
  return result;
}

