  '': { prefix: '', separator: ',', named: false, emptyText: '', keepReserved: false },
  '+': { prefix: '', separator: ',', named: false, emptyText: '', keepReserved: true },
  '#': { prefix: '#', separator: ',', named: false, emptyText: '', keepReserved: true },
  '.': { prefix: '.', separator: '.', named: false, emptyText: '', keepReserved: false },
  '/': { prefix: '/', separator: '/', named: false, emptyText: '', keepReserved: false },
  ';': { prefix: ';', separator: ';', named: true, emptyText: '', keepReserved: false },
  '?': { prefix: '?', separator: '&', named: true, emptyText: '=', keepReserved: false },
  '&': { prefix: '&', separator: '&', named: true, emptyText: '=', keepReserved: false },
};

function isScalar(value) {
  return (
    typeof value === 'string' ||
    typeof value === 'boolean' ||
    (typeof value === 'number' && Number.isFinite(value))
  );
}

function requireScalar(value, name) {
  if (!isScalar(value)) {
    throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
  }
  return value;
}

function truncate(str, maxLength) {
  if (maxLength === null) return str;
  return Array.from(str).slice(0, maxLength).join('');
}

/** Classify a value into 'none', 'array' or 'object' scalar entries, or 'scalar'. */
function classify(value, name, maxLength) {
  if (value === null || value === undefined) return { kind: 'none' };
